) AS (
  VALUES 
    (305::BIGINT, 'me cambie de uni y carrera por ella. Los exámenes son muchos, muy confusos y complicados, para los proyectos es buscar ayuda por su cuenta pq no explica nada que tenga que ver con ellos, además son enormes (pasé una semana con solo 3 horas de sueño) hace revisiones fuera de horario o sea chao tarde'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos exámenes', 'Deja trabajos largos']::TEXT[], '2026-10-01T00:00:00+00:00'::TIMESTAMPTZ, 'eef76224a11aa51380edd95feb3cf23323042605d4c7195f2b57e76b1d4aa87c'::TEXT, ARRAY[1020]::BIGINT[]),
    (305::BIGINT, 'La profe si es un toque complicada, pero es una teja de persona, explica super bien, da la mayoría del código, se preocupa mucho por sus estudiantes, si muestras interés te ayuda, se aprende mucho con ella, si pide mucho, pero es full lograble y se pasa con buena nota'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2026-07-31T00:00:00+00:00'::TIMESTAMPTZ, '86c839f1f917fd00bab7def7ea06d1e10617b2202afb2914bf23cfac59a34eb2'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'mala con ganas'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos exámenes', 'Exámenes retadores']::TEXT[], '2026-07-25T00:00:00+00:00'::TIMESTAMPTZ, '62d44f7b107ed1f8ad48365b8287f2fbf19966e5b3255c5d69ef0c02e4bf127e'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'A mi parecer, es una profe que si explica súper bien en clase a cómo tiene que ser para el nivel que es. Sin embargo, muchas veces se contradice ella sola con explicación y enunciados que ella misma hace, pero fuera de todo eso es muy buena persona y no tan mala profe.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2026-07-23T00:00:00+00:00'::TIMESTAMPTZ, 'a72ce7e04528a110cc668f59cb382d0d727005ebcfde1a38dad301cb7b38e3c6'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'La profesora es complicada, no lo voy a negar. En telegram son unos enredos que solo ella entiende pero la profesora es muy buena sin duda, explica bien y con paciencia si alguien se pierde vuelve a explicar. Su clase no es facil pero se puede pasar muy bien con ella si se muestra interes.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Brinda apoyo']::TEXT[], '2026-06-29T00:00:00+00:00'::TIMESTAMPTZ, '2df2b1f39def8ad5355f9a7132c1bdf8bed375e0ab864c4552fe70fbf5db988e'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'Sinceramente no la recomiendo para este curso si no llevó intro/taller con ella. Para alguien que no esté acostumbrado a su forma de trabajar y a los enredos del Telegram y Drive va a ser difícil porque ya todo el código lo da a su manera y lo único que hace en clases es leerlo como si fuera karaoke'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2026-02-23T00:00:00+00:00'::TIMESTAMPTZ, '40aabc4d9e40abd24564fed304689d64d6aded93bbea1217728689264a453977'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'No haga caso a los comentarios de la gente, ella ayuda si usted muestra interés, si quiere aprender matricule con ella, pero si quiere pasar fácil no, no regala ni medio punto a nadie premia a la gente que se esfuerza, los exámenes son complejos pero deja tiempo suficiente, normal por el creditaje.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2026-02-22T00:00:00+00:00'::TIMESTAMPTZ, '3bcf5419c819aaf4dd3b65af83d831b6ecdb957e214671e2c704353640a70f99'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'Con ella es muy fácil, los exámenes los deja jueves para entregar martes por lo que hay mucho tiempo y son relativamente fáciles porque es lo mismo que se ve en clase. Los ejercicios que hace en clase luego los pide como quiz, por eso se hacen bastantes pero es solo poner atención.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2025-12-12T00:00:00+00:00'::TIMESTAMPTZ, 'd6ad72f67f8c5acdd24774cc5c6c0a67c647a5e8e1af315d6117f887b6626c02'::TEXT, ARRAY[1151]::BIGINT[]),
    (305::BIGINT, 'La profe es un amor, se preocupa porque usted entienda. Los quices son facilísimos pero deja como 20 quices/tareas. Los exámenes son larguísimos pero tiene 4 días para hacerlos. Haga las varas y debería pasar fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2025-11-28T00:00:00+00:00'::TIMESTAMPTZ, '5857006bb0b4fd751728293488602fa912bb79c7e41355e8d65aa1f565cb13a4'::TEXT, ARRAY[1151]::BIGINT[]),
    (305::BIGINT, 'Si tienen la oportunidad de matricular con esta persona, desaprovéchenla :D'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2025-09-14T00:00:00+00:00'::TIMESTAMPTZ, '062d6b7414f2749318a3dd708d578357bd5c7d0db31243453a6fcfe4547fdfdb'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'La verdad no la recomiendo, es un curso que se hace super pesado. La mae es muy intensa y quiere hacer las cosas solo como ella quiere. Además su voz es empalagosa. Lo más importante es encontrar una buena pareja de trabajo.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2025-08-01T00:00:00+00:00'::TIMESTAMPTZ, 'b1e56db88097f997f9e578c2b458c6f2e509966427c53e21cdbe3f4dfc4f6061'::TEXT, ARRAY[1151]::BIGINT[]),
    (305::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2025-07-28T00:00:00+00:00'::TIMESTAMPTZ, '8f0110b3e0991f0853212e979578da7bdfbe95a7ef0841c1b0c0f0105899513d'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'La doñita no es mala como persona, sino como profe, hace demasiados enredos en el Telegram que tiene, se pierden archivos que ella manda y se contradice cuando está explicando, pasa dejando trabajos, aparte de que no explica bien en los examenes ni tareas, pero para calificar siempre baja por algo.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2025-07-07T00:00:00+00:00'::TIMESTAMPTZ, '9cf7aa5a3a30771f31a2edc254c367e3711ac5b5085e42756d669c85b15c8d97'::TEXT, ARRAY[1020]::BIGINT[]),
    (305::BIGINT, 'HORRIBLE. La forma de calificar que tiene la profes Ivannia no tiene nada que ver con la carga de trabajos que deja. Además, no explica bien, entonces preparase para investigar por aparte, es exagerado el montón de tareas/quices. No permite ser flexible con la programación, solo es como ella quiera.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-03T00:00:00+00:00'::TIMESTAMPTZ, '78814a537e388a94eb739306f4197b478b65a9c154e73e650c49348dfe4a0f6b'::TEXT, ARRAY[1020]::BIGINT[]),
    (305::BIGINT, 'Los trabajos que deja son largos pero se aprende mucho autónomamente. Ayuda con actividades de puntaje extra. Pero los exámenes pueden ser muy rudos y no explica muy claramente las instrucciones de proyectos, ni tampoco dice como hacerlos. Es buena gente.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2025-05-29T00:00:00+00:00'::TIMESTAMPTZ, '4963633fa27bf57ad072c1f84a6fed71d81e873e57ee796859e2acbd5342132c'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'Es una profe algo complicada, si mantienes el paso de los primeros trabajos puedes pasar sin muchos problemas, pero las primeras semanas tendrás que aprender bastante del lenguaje de programación con el cual vas a trabajar.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2025-02-07T00:00:00+00:00'::TIMESTAMPTZ, 'de01dae789f3f33c761da8abfd8ea030374b1cc1d2d5e3af17c3c575b1c0cdbb'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'Explica bien en clase, y es muy paciente cuando atiende dudas y hace quices fáciles, deja tareas todos los días, permite trabajar en grupo, las instrucciones de las tareas no son tan claras'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2025-02-05T00:00:00+00:00'::TIMESTAMPTZ, '67c069187b83414636b0ddcedcebdc5ff9058d8f721e03d2a315ff5c517b2bde'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'Honestamente este curso ha sido una verguenza. No explica nada en todo el curso, solo copia codigo y repite lo que hace, asume desde el dia 1 el conocimiento del estudiante. Aunque es buena persona es terrible profesora. Los examenes/laboratorios NO SE ENTIENDEN y ademas es mala para evacuar dudas.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2025-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'bed3c20a691dfa7ee01c22e59e613930b69585fe3658c23c0b31cabf5058137b'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'Evitarla a toda costa, explica muy rápido y mucho en una misma clase, los trabajos y exámenes no son claros. Al principio se muestra simpática pero a lo ultimo ya no y no es buena ni amable para evacuar dudas por mensaje'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2024-12-30T00:00:00+00:00'::TIMESTAMPTZ, '69cd0e05060ac89d4242fa8137a86f3dc8838be91a3b9b1c4fd7f597a05510fd'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'Buena explicacion en clase, los examenes son confusos y las corridas tienden a tener errores y si no le preguntaste algo en clases olvidese porque no aclara nada x mensajes, y sus asistentes tampoco ayudan en nada, examenes medio sencillos'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2024-10-22T00:00:00+00:00'::TIMESTAMPTZ, '7a613f3960a63ea7cef71c2254b43fd4ade7aeea00190b9781ee2e7180cc5b7c'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'Deja muchas tareas y exámenes, que siempre hay entregable pendiente, pero eso no le veo problema, es bueno, el problema son ejercicios confusos y poco ortodoxos, deja una explicación muy general y a la hora de revisar revisa muy detallada las partes confusas por mala explicación, no te ayuda en nada'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2024-10-09T00:00:00+00:00'::TIMESTAMPTZ, 'f193735b40a38d6e6c5a3538ef97c684350015322ff16294b58d87bf1b48138b'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'Vean, si le ponen mucho y tienen cuidado en los proyectos es muy buena profe, sino diay no, es muy organizada con los trabajos y en semana 16 se sale de todo, eso si la mae va voladisima asi que es bueno ya tener bases desde antes, y si no las tiene pongale bonito, es vacilona'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2024-06-22T00:00:00+00:00'::TIMESTAMPTZ, '5789001dc042e3635969d41799af728246a51267b6fb981fe1a367353a433979'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'Profe muy mala, no explica para nada bien, si uno le pide ayuda, le explica pero usted queda igual a como le preguntó, no deja las cosas muy claras. Las tareas, laboratorios y examenes vienen con instrucciones no muy claras y las corridas a mano del código que hacen son tediosas y dificil de entende'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, '8092e767c1d6f3c637bd12680924b1c4c339b006b3506e66ecd25f1cdbc73832'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'Con ella el curso no es pesado. Da buen tiempo para entregar evaluaciones y explica bastante bien en clase. Los exámenes son rudos pero si se sacan. Lo único malo es que cuando uno se comunica con ella fuera de clase, le cuesta explicarse, entonces uno queda igual, sin embargo es una buena opción.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Muchos exámenes', 'Exámenes retadores']::TEXT[], '2024-05-31T00:00:00+00:00'::TIMESTAMPTZ, '340ec04302f59caecfddbe79d8b7faa9710feb68c682bdbd554e5480d4843c81'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'La única razón por la que sus trabajos son difíciles es que NO SABE EXPLICAR. Sus explicaciones son muy generales y algunas no son ni siquiera coherentes. Cuando uno hace preguntas ni siquiera se esfuerza en mínimo explicarlo bien o dejarlo claro. Todos confundidos y solo los deja de segundo plano'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2024-05-27T00:00:00+00:00'::TIMESTAMPTZ, '5570a2edd37f19a2870490fcf40f9352e1875f688931dd8854c4fb7a470b8985'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'Deja muchas tareas y quices; son muy fáciles, pero deja como 20, así que cada uno vale como 1%. El curso es fácil, y la profe explica muy al detalle y paso a paso, y los exámenes se hacen en la casa y hay mucho material de referencia. Lo horrible es que pide todo a mano, y los ejercicios son largos.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Exámenes retadores', 'Clases excelentes']::TEXT[], '2023-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'e564af530d783b6c78b8631e1d9ea4b6a63ec346c8eb6dc0995f18c96099a62c'::TEXT, ARRAY[1151]::BIGINT[]),
    (305::BIGINT, 'Profe muy organizada pero que va, no brinda ayuda ni de broma. Ni con los tutores de progra puede uno preguntar porque los proyectos tareas y examenes son tan complicados y confusos. Deja muchas tareas. Hay mejores profes, busque uno que le ayude en especial si es primer ingreso.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos exámenes']::TEXT[], '2023-11-07T00:00:00+00:00'::TIMESTAMPTZ, 'fc401b24af10e5346289f35544de6f7bb481c796bb5b46372566d09d118b9f93'::TEXT, ARRAY[1020]::BIGINT[]),
    (305::BIGINT, 'La verdad no tengo ninguna queja sobre ella. Es muy detallada para explicar y lo vuelve a hacer las veces que usted lo necesite, contesta muy rápido por tele y las evaluaciones son sencillas. Buena opción'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'La participación importa']::TEXT[], '2023-06-27T00:00:00+00:00'::TIMESTAMPTZ, '180f3e97b9b28e6922cccd6a9dc4de542537a31d3b568b850f8b9d87bb581e63'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'Deja tareas y haces quizzes todas las clases. Es facil llevar el curso con ella, intente caerle bien y todo se le hará más fácil. Pasa lista de asistencia tanto en virtual como en presencial en todas las clases'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '3125330ac50475d0abbb2964973085661840c68770f727dfc939d49a5f731d1b'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'Explica muy muy muy bien, el problema es que va rapídisimo cuando explica entonces no da tiempo de apuntar si intenta entender y no da tiempo de entender si intenta apuntar. Sin embargo ella es muy simpática y además hace el curso muy fácil, muy recomendada. Deja mucho trabajo eso sí pero es fácil.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2022-12-27T00:00:00+00:00'::TIMESTAMPTZ, '91ed79faee00e25f545d95ee7f8a47ebcb594686a9e0a0b6f26fbef30f73fb6b'::TEXT, ARRAY[1151]::BIGINT[]),
    (305::BIGINT, 'Llevé la clase con Ivannia, la verdad no lo disfruté, si de por sí la materia es horrible, la profe lo hace aún más pesado, cuando se entrega una evaluación de un solo deja la siguiente, cuesta recibir ayuda por su parte y no tiene piedad al calificar'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2022-12-13T00:00:00+00:00'::TIMESTAMPTZ, 'aef7162742f8305f3a541fc30d6fc8ac52e039f2b4e6dcf230631f8e7869c82b'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'Si logran agarrar el ritmo de la profe, se pasa super sencillo. Hay que poner bastante atencion en clase y copiar todos los ejercicios para que la profe le regale los quices y tambien para que puedan hacer los examenes. La profe es muy tuanis y no califica duro.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2022-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'bf4a7d1d101105e89248f97fce514fcbe284cedcac8a8904a3bae508ca09a802'::TEXT, ARRAY[1151]::BIGINT[]),
    (305::BIGINT, 'No les recomiendo esta profesora, se enoja si usted le pregunta algo, deja proyectos demasiado complicados y espera que sepamos programar algo que ni siquiera explicó bien.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2022-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'e04c6c4070940f402ac1bc5ffe213c1891106169b4e08910661b10c2f17de48e'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'Resumido, vieja HD***'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2022-10-22T00:00:00+00:00'::TIMESTAMPTZ, '067e0bc8fddc6cdc79f19e4367ee688e53bc1be8b182d90bdcb711413bcd41fc'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'Esta Roca parece arroz con mango al chile, toda enrredada y deja exámenes que sia tan tonto, sinceramente está profe no se la deseo A NADIE.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'feaf33260320c22619415a192f8bd81aecbedc6287ca6e1193e403014d4e7703'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, '0 recomendada, proyectos voladisimos, no los explica, espera que uno entienda cosas que nunca se han tocado en clase, 0% recomendada, si tiene cualquier otro profe para escoger, porfa hagalo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'b670d37bd57d611c20544cd795301a6a97dac5a49ab94d2d8a351aef42d07b2b'::TEXT, ARRAY[1022, 1020]::BIGINT[]),
    (305::BIGINT, 'Esta es una excelente profe para llevar este curso, los temas hacen que los trabajos sean largos y están enfocados 100% a la matemática. Nos hizo exámenes sencillos pero largos donde tienes que tener mucho cuidado, lleva las cosas al día, asiste para ganar la mayor cantidad de quices y pasarás.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2022-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'b837bbd06b1fba143b5c39f9ab4892fec9f2fb64e73219738c3da90c985a6c97'::TEXT, ARRAY[1151]::BIGINT[]),
    (305::BIGINT, 'Mal profe, odiosa, muchos ejemplos en clase pero en los exámenes la vuela y pone cosas re complicadas y no ayuda mucho con consultas, si sabe de progra pasa bien pero i no considere 2 veces meter cursos con esta señora'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'd4907fa5a547cf9b97856375758630e4e88369a9c3a8f4c29270988230c94b02'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'a6303c6b4eec918d8ab544229edb1add39e6e1a505e552e927231b4ff5bb49ac'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'Leyendo comentarios me doy cuenta que la profe es la mejor del mundo para I.O pero para progra no jaja bueno, a todos los que van a llevar I.O metan con ella, si ud no pasa el curso es porque seguro no asistió a ninguna clase o de paso no envió una sola tarea, ella hace del curso algo facilisimo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-06T00:00:00+00:00'::TIMESTAMPTZ, '084b3b211dc2079028b52ae02e639bf318ae5b62f4a41f2805108f9c8777da82'::TEXT, ARRAY[1151]::BIGINT[]),
    (305::BIGINT, 'Se aprende a programar de forma fácil con muchos ejercicios en clase. En los examenes califica duro. En las progras de Taller toca aprender a programar sólo, porque enseña las cosas después de que ya se ocuparon en evaluaciones. Es ordenada con el calendario, se terminan las clases antes.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2022-06-03T00:00:00+00:00'::TIMESTAMPTZ, 'f03b835752541cf352e0af5626f8e3cdaa43da4e26c445c0dc75a485461be6f1'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'No la recomiendo para nada, lo unico bueno es que explica muchos ejercicios en clase que hacen que uno entienda un poco, pero los proyectos y examenes son la cosa mas confusa que hay, en los proyectos brinda 0 ayuda e implementa cosas super raras que uno tiene que ver como la juega para ver que son.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-03T00:00:00+00:00'::TIMESTAMPTZ, '0f34e7ddcb9b73bfd536d326dc430b87a58b9d62709d80d1489faa3ab5165fd6'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'Al principio del curso se presenta como una buena profesora, plantea un orden impecable, pero luego de las primeras semanas todo se cae, envía 5 calendarios diferentes y no lleva un orden claro de las asignaciones. Las instrucciones de las tareas y proyectos NO son claras y se enoja si le preguntan'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2022-06-03T00:00:00+00:00'::TIMESTAMPTZ, '7fd707945b18f19977b8ba2c0ab2198265fef62ee689cb27121929e0838a774a'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'A esta profesora no la recomiendo para nada. Si bien explica muchos ejercicios, las evaluaciones grandes no tienen nada que ver con nada de lo que explica durante las clases. Los proyectos que deja son equivalentes a aprender programación por cuenta propia, ya que de parte de ella no hará nada.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2022-06-02T00:00:00+00:00'::TIMESTAMPTZ, 'b3521a5a3eb40dcbaa5ef92309f1143dc4e6b8f593593cc6c367527db96a4c17'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'No la recomiendo. Es muy ordenada con los trabajos, pero la claridad de estos es PESIMA, cuesta mucho entender lo que hay que hacer debido a falta de buena redacción, desde tareas pequeñas hasta proyectos. No ayuda absolutamente nada respecto al lenguaje de programación'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'c297694cb87841e424ecc02839059bfcae151b2d06769444968a7c030470af22'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'La cantidad de trabajo en el curso es exagerada y califica demasiado duro ,ni llevandolo solo se puede estar al dia, no deja de recordar lo complicado que es el curso cada que puede y su metodología despues del primer proyecto es confusa de entender, es muy impaciente con las dudas, no la recomiendo'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2022-01-14T00:00:00+00:00'::TIMESTAMPTZ, '507d67ea5a84868fb91f1494ad1958d7bcd43fe95ffe98afee90a8b2bf037942'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'Es un curso que se pasa muy fácil con ella por la metodología que utiliza. Hay tareas todas las semanas las cuales son que sirven mucho para los exámenes.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-20T00:00:00+00:00'::TIMESTAMPTZ, '7764b9cb9a9eb24dfa39577cc5b35bca88485e50702248675719dc2a432b9232'::TEXT, ARRAY[1151]::BIGINT[]),
    (305::BIGINT, 'No la recomiendo para nada, si bien al principio parece una buena profe, conforme avanza el semestre deja eso de lado. Muchas tareas (lo usual en el curso), pero las indicaciones son cero claras y si usted le pregunta se enoja y si no se hace lo que ella quiere en los trabajos, le pone un cero.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2021-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'eea34217bd363e6fbc763c9c7c082ed4899d2fd0c41cf2d9235544675346cf89'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'Explica bien. Ella no inicia con teoría, inicia programando de una vez. Los problemas llegan en exámenes y proyectos. Algunos de los ejercicios de exámenes pueden resultar confusos y difíciles de realizar. En la parte del proyecto, son interesantes pero difíciles, le va a tocar investigar mucho'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, '2e27bfa9dc046b5ee2eca56f6246b7f0e65b4b1d250dc379240dfa2142aaf528'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'Aunque es un poco desordenada, hace bastantes prácticas en clase para que todos entiendan y manda tareas cortas para practicar. El proyecto si es bastante largo. Se le pueden realizar consultas por Telegram y contesta súper rápido.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, '34ee8c5f72a09ac4983135c213e2f3a9a0b31d3436e1717652e7347430207f3c'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'La mejor profe para llevar este curso, explica claro y conciso, hace ejemplos en clase que luego salen en los exámenes. Sí deja bastantes tareas pero todas terminan siendo práctica para los mismos exámenes y nunca son más de dos ejercicios. Tiene mucha paciencia para explicar de nuevo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-15T00:00:00+00:00'::TIMESTAMPTZ, 'a209d913a297663a536a4ecdfe4b98d2682d242459f89d757dac622538ab6a62'::TEXT, ARRAY[1151]::BIGINT[]),
    (305::BIGINT, 'La profe es muy desordenada. Deja tareas o laboratorios todas las semanas, y las instrucciones no son claras, estos son fáciles pero los exámenes no. No acepta reclamos, y la ayuda en consulta es de poca a nula. Trate de tener algún compa con quien comparar. Pasa lista todas las clases.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2021-07-15T00:00:00+00:00'::TIMESTAMPTZ, '23ef9212179579656d5d14d77647cc21de8dcecb9fc066e149aaf2a23575ec1d'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'La profe es muy desordenada, pero en las clases se le entiende lo que hace. Deja tareas o laboratorios todas las semanas, y las instrucciones no siempre son claras. Si lo va a llevar con ella, intente llevarlo con un o una compa, para que no se le complique tanto. Pasa lista en todas las clases.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos exámenes', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '700cf85bb94ea610c82d5fca7aa384197fba794c491a5043574f5b1ef0886203'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'Muy buena profesora, muy ordenada con los trabajos y las notas, las clases explica muy bien, si se adaptan al ritmo de la profe pasan bien el curso. La última progra nadie la pasa, pero después de ahí todo en orden'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-10T00:00:00+00:00'::TIMESTAMPTZ, '7075560a8b0b7b9bd9449e4f3f93477eff5a164870142a8958a6b2cc2392bbc8'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2021-07-02T00:00:00+00:00'::TIMESTAMPTZ, '87ef656035580c796fa91c48265d87202720a6b5c742c225db2bac8b63b56824'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'El curso no es complicado pero deja tarea o laboratorio cada semana. Las instrucciones no son claras y si le reclamas algo se vuelve muy grosera. Pasa lista en casa clase y si no estas tienes que hacer un trabajo muy pequeño extra. No justifica ninguna ausencia.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2021-07-02T00:00:00+00:00'::TIMESTAMPTZ, '1889cac1ecc53718813178fa0349a830f6e85dd2f0253afabab65d18936c2b2e'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'La profe tiene algunas cosas no tan buenas, pero en general no es mala y dentro de lo que cabe no es difícil pasar. Si en su carrera no es 100% necesario la programación, la recomiendo. Muchas veces no se entienden sus instrucciones en tareas/exámenes, y hay que preguntar bastante y se entiende'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-30T00:00:00+00:00'::TIMESTAMPTZ, '0e2f3ae7cd1103af4edd23a9d32992f33953d5b6740b2a987c4b4e6d3638c0f0'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'La profe en sí no es mala, hace el curso bastante llevadero, las instrucciones que ella da son bastante malas, hay que adivinar o preguntar bastante por telegram, y aun así sus "aclaraciones" son bastante deficientes, si en su carrera no ocupa programar matricule con ella.'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-25T00:00:00+00:00'::TIMESTAMPTZ, '40f9af304eb22e86b51a46ac0323d99a4e7d391e1c97e081b891e08730deb4c0'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2021-03-09T00:00:00+00:00'::TIMESTAMPTZ, '9981f4b9412fee3236db7e3c5246f6a040ad87ead90bef58f7c20df978a9e5e3'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'Para proyectos no da las intrucciones claramente, asi que termina cambiando cosas a medio proyecto, es grosera y se indigna facilmente. No acepta trabajos entregados por segundos tarde. Si no se cumple un requerimiento de sus trabajos, ya tenes menos de la mitad de la nota. Revisar con el asistente'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2021-02-10T00:00:00+00:00'::TIMESTAMPTZ, '569ec3bca31bc75850b5976f58181255f18fb0e1e66f1a317682bfb98d0489fc'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'Los proyectos son largos pero fáciles si se hacen con personas adecuadas. Deja muchas tareas pero esto hace que la nota no solo dependa de proyectos. En general la profe es muy buena'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'ae89a38ae8b607d9f7ad7cd695b71f7084815526e809e8975058e7338310f010'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'Puede dejar varias tareas y quices, en muchas de estas se le cuesta entenderle lo que hay que hacer, pero es buena profe, explica bien y si alguien no le entiende lo vuelve a explicar.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, 'd59dda0a4ae1e99321a97c729b5c45993c541e0e9b94a4dd3cd38d37e2bd02bc'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'Explica muy bien y claro los temas de arboles, listas, grafos y sus algoritmos. Deja muchas tareas que usualmente son cortas y no demandan mucho tiempo. Los proyectos son escalonados y la verdad si haces bien el primero los demas seran pan comido. En general buena profe y se aprende.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2020-12-21T00:00:00+00:00'::TIMESTAMPTZ, 'ba0308783641e022e4e64d69e2d8dd3dff192a92b03a5d50af86b430ef45ebca'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'La profe es demasiado buena nota, si cree que le iba a ir mal y pasa es porque ella se tocó el corazón sin embargo es muy desordenada las especificaciones de los proyectos son otra cosa lo que revisa, intenté tener muy claro que es lo que hay que hacer pero por lo general usted pasa'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '70e78cc6611699e396dab783998d8cfcc691448068fffeac04e19a4f7bdcc296'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'NO lleve con ella, es una desordenada y no explica bien Muchos enredos al usar muchas plataformas (classroom, tec digital, facebook, telegram)'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '2271d946079303eecef5cd1a3949f48de469554c116b1b487455120741dfd0d3'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'Si tiene buenas bases de programacion pasa el curso relativamente fácil, esto siendo presencial. Si tiene o planea llevarlo virtual NO matricule con ella, desordenada es un piropo. Tanto así que nos pidió que le explicaramos el examen final a un compañero por Telegram porque ella estaba muy ocupada.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '914fb14cc439525c2085d6b18d5a78152d4a27b130ff70e50363121ece699122'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'Es buena explicando, pero es muy desordenada, los trabajos son un poco enredados siempre hay que preguntarle de nuevo, dura mucho revisando.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, '1f84e21586407d55dc3aa70bab6d9ca0297a686c35a3b11bd7e2572a6e5edf91'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'Explica muy mal. Se enreda entre las especificaciones de trabajos y lo que realmente espera que se haga. Prepárese para proyectos largos y confusos, pídale por privado que explique mejor las especificaciones o le irá mal.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, '41d65a194d6c16e667bdd9a60efef4d627482bcfd252e50c3de42e0cd6e9be42'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'Muy buena profe, sin duda se aprende y se pasa el curso.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'La participación importa']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'b7110587d0d87d028114ae32c5475f9bf41b9f548646922d499c6acaffc113fa'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2020-08-13T00:00:00+00:00'::TIMESTAMPTZ, 'a0461995db8a8a24c86c4dd83bd358c53c0cb964386e591c7c671df48e10c5a5'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'Teóricamente sabe bastante, pero en práctica su conocimiento se queda muy corto para una profesora. Las instrucciones de las progras y tareas no son del todo claras, dejan mucho a interpretación y, al hacerlo así, le baja puntos. Da poca o nula ayuda con respuestas indignadas.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2020-08-09T00:00:00+00:00'::TIMESTAMPTZ, 'a5b2dd43235d7a11c87a5db31285d547fcfc1e636aab92d941d14ec32315a9f6'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'Es increíblemente desordenada. Las instrucciones están siempre muy mal hechas, y eso afecta las progras. Cuando uno le hace dudas responde bastante mal. Es profesora de computación y parece que no sabe usar una computadora. Si es virtual, NO LO META, si no, considérelo, es estresant pero aprende sol'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2020-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'b562c1a8a876e7221919421cb54697423ccee1676aae7ec85e403d58ec6516d6'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'En intro es muy buena profesora se las recomiendo!!! En taller no tanto... A veces no explica algo y te lo pide en la progra, o te pide algo y en la progra no lo revisa.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2020-02-03T00:00:00+00:00'::TIMESTAMPTZ, '8548ee4780a2ab719de5e62b15db87d82514b2b9e46bc0133f4e40c2952c3c54'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'Personalmente, es de la mejores profes para explicar la materia. Deja tareas todas las clases. Es buena persona y profe. Es muy desordenada. Para algunos las progras pueden ser rudas, pero, para mí, son más como de dedicarle tiempo.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2020-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'ec7fe4b56f69e4ad34832ca660e53b6ec5f6309e7a9553e38749dd6049226c88'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'Deja tareas TODAS las clases para compensar su incapacidad de explicar la materia. Sus progras son rudas, se enreda mucho , llega muy tarde prefiere viajar robandose el salario de proletariado.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2019-12-26T00:00:00+00:00'::TIMESTAMPTZ, '6641d45a4782c966a58a2d657c7a966420a95fb7ee8314c411ebfb05be652eca'::TEXT, ARRAY[1030]::BIGINT[]),
    (305::BIGINT, 'Es buena gente , explica bien y el curso es fácil , las tareas son largas pero fáciles y son muchas , da muchos quices en clases por solo ir , los quices son a cuaderno abierto o en parejas y los exámenes también y a veces para la casa.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2019-11-23T00:00:00+00:00'::TIMESTAMPTZ, '804df13c041c179e8966e3591b5669f91615a49c76d7d48b2f89311b96f28b5e'::TEXT, ARRAY[1151]::BIGINT[]),
    (305::BIGINT, 'Bastante buena. Explica con paciencia y repite las veces que sea necesario. Lo malo es que es muy desordenada con las evaluaciones y llegamos a hacer el 4to examen sin saber la nota del 3ero. Pero son exámenes para la casa y en parejas. Me molesto que entró algo en el examen que no vimos bien.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos exámenes', 'Brinda apoyo']::TEXT[], '2019-11-21T00:00:00+00:00'::TIMESTAMPTZ, '062fc0732ee69a3d90ed62f965755c6ae5126197daa62725f6d862b6527442e8'::TEXT, ARRAY[1151]::BIGINT[]),
    (305::BIGINT, 'La profe no es tan mala como dicen, explica bien la materia y si tiene que repetir la explicación lo hace, pero las instrucciones de los proyectos suelen ser muy confusas, sin embargo, no califica tan duro y la evaluación siempre es sobre 120 / 130 puntos. Se aprende bastante, pero no es fácil.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2019-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'c0f0d5273cf3ced41ed06bde0f3e8d5119d3558297450b00b8b8a62ab205f3d6'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'Si no les queda de otra pues metan con ella, pero si hay alguien mas les aseguro que no se van a arrepentir. Simplemente es mala profesora. Puede complicarles el curso adrede y lo hace seguido. Tienen que estar atentos a cambios repentinos que puede que lo perjudiquen y ella no hara nada por ayudar.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '1aeb5b77718f9d6a08479719620d8c72995b46db5fd9c20afc74709d3929b685'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'Es una de las profesores más irresponsables con las que he llevado. Las explicaciones para los trabajos nunca son claras y cuando se le pregunta cambia todo y se toma tiempo de clases para chismear. Si le caes mal no te va a evacuar dudas y va a ser muy pasivo-agresiva.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, '38f90f8e7310c0e1c3bae93c25fb2b6189985f50ef3b086e8466e5789b3f379c'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'Demasiados trabajos, multiplica el costo de créditos del curso por 2 y lo que solicita para los trabajos es 0 claro pero califica súper específicamente. Un asco de profesora'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'e3e466cca203aa79d811a72346032c26632ecfe68d5e0532b5f086bf71f1dadf'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'Simplemente busque algo mejor'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2018-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'c7cefb2d7696f7d17da4ccd966f5eb3b1f221a7f748b08753b0825cee557ddc1'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'Siempre llega tarde. Explica bien. Los enunciados de los proyectos son 0% claros y traen errores que cambian todo el alcance del proyecto de un momento a otro. Una vez le hice una lista de preguntas del proyecto y contesto: "Algoritmo". Por que? No se. Todavía tengo pesadillas con eso.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'a6a99c5832b742ce51f919fb749e464faaea407069c296103aa0984a5d52538b'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'Buena profe, hay que dedicarle mucho tiempo pero se aprende, aunque todo debe ser por cuenta de uno. Las progras nada que ver con lo que se ve en clase, muy desordenada. La recomiendo.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos exámenes', 'Brinda apoyo']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '5a578735b2027776c50b4fdebbc7bc94bcd7f702625a8375e115c8a81593bd7d'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'Se enreda mucho pero es buena profesora.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'bd5f9a45f7643154b95a324d5068d5020a3248565c370bb2831d0d984a5675dc'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'Es fácil pasar si se hacen todas las tareas y laboratorios. No califica super fuerte. Los exámenes son largos pero parecidos a las tareas.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'f25f12704c474d21c79af6ba6000d738d8191529a5dde8e3cb5f6efb1a898726'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'Califica suave, no se aprende mucho pero ayuda para pasar el curso. Si su carrera involucra mucha progra no meta con ella'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-17T00:00:00+00:00'::TIMESTAMPTZ, '4357a8ab0c9bcdd88cb20ab896b9b2ace4a8c3facfadcd71ab777def627f1706'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'No me parece una buena profe, no es mala tampoco, pero si tiene otras opciones considérelas. Aparte es demasiado desordenada.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-14T00:00:00+00:00'::TIMESTAMPTZ, '5f3c70f764eca3099752f1617c461b14d61789349a1216d5774cc273fe4e58d9'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'La profesora es buena, pero el fallo que tiene es que a veces va muy rápido con la materia (un problema, ya que muchos de los que llevan el curso no saben programar). Es un desorden revisando, y deja tareas casi siempre. Si puede aprender un poco de Python antes de llevarlo, va a pasar fácil.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'f66375e6f966182ccc7b5a1f39be1ec03e9826153e0f4970b977a3258b60ea11'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'Es bastante fácil aunque en los exámenes se le sale uno que otro problema difícil. Más adelante podría pegar de vuelta el hecho de que no mete proyectos muy complicados, pero sí se aprende bastante.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-17T00:00:00+00:00'::TIMESTAMPTZ, '6d42bc4bbc8c2c3ff66244ddd7a0f360c487c84883c65dbffa89dca605a6121d'::TEXT, ARRAY[1020]::BIGINT[]),
    (305::BIGINT, 'Buena profe, llevaría otro curso con ella'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-07T00:00:00+00:00'::TIMESTAMPTZ, '5767eedab842228802b10bcf19a9243d67cc3957ae82b95af8c93506c44b78b8'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'Bien, hay que trabajar en las progras, hace examenes tareas cortas. Tambien tareas y quices casi todas las semanas.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '96341cdc64932d8e53a6a846d998fc0c50eef07beb9f120910cb3400777f1ea7'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'Excelente profe , desordenada pero de las mejores para aprender datos'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '39a94f8c3b2d04c83f51782cd7e907810b2e88eb98a1406275ff9566e413f20c'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'Mala profesora, impuntual y desordenada en las revisiones de proyectos, las clases y los trabajos que deja. No sabe explicar.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '47d2d3273ff2c6f284314a755e5db4388aad096074a402389b0e5e5f89211a21'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'La profe explica bien pero si a usted le cuesta mas bien lo basurea y no busca ayudarle. Para calificar es un DESORDEN. Pero es fácil pasar.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2017-06-24T00:00:00+00:00'::TIMESTAMPTZ, '5d75f7fe310c254cda317d7bbec54daf28b7a6928c3d2d74587ab9d90333e1db'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2017-02-01T00:00:00+00:00'::TIMESTAMPTZ, '97fb32b58548c2a0051926c81d8c6d925dcd2cbf5b3af0b032631b509d806c65'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'El curso es bastante fácil con ella. Las explicaciones son casi siempre muy claras. Ayuda si es necesario, es muy comprensivo y una excelente persona. Las clases son entretenidas y se practica mucho.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-31T00:00:00+00:00'::TIMESTAMPTZ, '7a57d3af617d307ba48749b0de0685564192f893fc91ad19377e9d6d0cccb8a5'::TEXT, ARRAY[1151]::BIGINT[]),
    (305::BIGINT, 'Excelente profe, explica claro, deja bastantes tareas que ayudan a repasar lo visto en clase, aclara dudas y se interesa porque sus estudiantes aprendan, es muy buena gente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-27T00:00:00+00:00'::TIMESTAMPTZ, '7b551a5b019433a5d02d179db3daef3b908c1137d320faa23e7c313fc069365b'::TEXT, ARRAY[1151]::BIGINT[]),
    (305::BIGINT, 'Lo lleve en verano y las clases siempre fueron bastante claras, deja varias tareas y eso te ayuda a que la nota mejore bastante. Las clases son amenas y la materia si pones atencion en clase resulta bastante sencilla.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-27T00:00:00+00:00'::TIMESTAMPTZ, '046bdd8ac08ec6af2ef2131bb41e8ba055fc7ee4739f7721ca653fff8c0f2c77'::TEXT, ARRAY[1151]::BIGINT[]),
    (305::BIGINT, 'Deja muchas tareas, los proyectos no son faciles pero tampoco imposibles con un poco de tiempo que le dediques lo vas a lograr.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2017-01-19T00:00:00+00:00'::TIMESTAMPTZ, '75c227bebc118c5c8615437daa621d8aaeffa1a7bf2cc851b92f4c1fb7c86a3c'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'La profe es muy buena nota, solo hay que ser responsable con las tareas (deja todas las semanas) porque eso salva un montón, las progresa con complejas pero no imposibles, califica normal, en general es importante ponerle no importa el profe que tenga ya que programar requiere mucho trabajo'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2017-01-19T00:00:00+00:00'::TIMESTAMPTZ, '84eefb90beb55aa132284f1381a7e6fed63d4f52f893b57b165ba6677f08582d'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'Es buena profesora. Explica de forma excelente. Deja muchas tareas pero eso te ayuda mucho a aprender bien la materia. Lo malo es que no especifica bien las cosas en los proyectos, a veces quedan cosas sin aclarar.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases excelentes']::TEXT[], '2016-12-03T00:00:00+00:00'::TIMESTAMPTZ, '9f60c9faad892f05a15cd875d6e12c77720ef8856bf00a7aebcf0ef8f51a7a2a'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'Es buena de cierta manera, da la visión de lo que tratan los temas y lo deja claro, pero usted debe programar todo de cero. PEROOOO...... Es un DOLOR con las progras, en las revisiones da ganas de estrellarla con la pared por lo desordenada.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'd3745a6d240130a5f7cf7b27d1b6dfb36216cc9efec956ebfcad2dcae404c864'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'Es súper buena nota, y la verdad con ella se pasa fácil si uno le pone. Los exámenes de intro son facilísimos, las progras son un toque más difíciles. Lo pone a investigar mucho. El único defecto que tiene es que llega tarde a las clases.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'cd6eeff85de4b9437f92772dbc3aab75333f46fedfc06e4887a5e090b76fd53a'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria']::TEXT[], '2016-05-13T00:00:00+00:00'::TIMESTAMPTZ, 'e05202e8b190558baf7082e567a3724f040d0b999d6151f45324b48b19598070'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'Una profe algo ruda. Le agrada que uno busque todo solo, pero si ve su esfuerzo algo le ayuda (pero casi rogándole). Llega muy tarde a clase (de ahí que uno aprenda solo).'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Da crédito extra']::TEXT[], '2016-03-19T00:00:00+00:00'::TIMESTAMPTZ, 'c975c1ba3e8f733d79dfdce4bc9d6a29549a079ce69e3f9479fcec87a32a4b78'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'La profe enseña lo necesario, si está es una carrera que después tiene que llevar algoritmos le sugiero acompañar el curso de ella con algún curso en línea de python, como en Coursera o Edx.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'f0953acd4673276e7526979a0f288ab1c20e3f9f371ce7fb35e335df66ed2b60'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'duro pero recomendada'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-19T00:00:00+00:00'::TIMESTAMPTZ, '58686952947da7b593f5bd2b784c8002ef1983cd56c29a1a65af46d999e2c868'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'Recomendada (Y)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-09T00:00:00+00:00'::TIMESTAMPTZ, '2d429183a9dfbbf63daf607e6ad34fd9e7cf08b6745fce7e283378e441baa16b'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'No es buena para cursos introductorios, no brinda ayuda a los estudiantes que llevan el curso por primera vez, no la recomiendo'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-04T00:00:00+00:00'::TIMESTAMPTZ, '1f5550bda6a8308e9aac3c01556681fc3c45061bcce2249df5c0bfb6904a9034'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'Grafos?'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'da040e625fdc7ef72a43353fa1ebf76b668eacfad37807b6f8c7504d22aa5e01'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'No es buena para cursos introductorios, deja al estudiante que haga las cosas solo. Es la mejor para llevar el curso por segunda vez, pero por primera vez nunca, ella no es tan buena para un estudiante que esté empezando.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'f63c44ec5441f2adae4343b96fdda05c6b9cdfbdda870edc2972c3c61e94ae29'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'Las clases son muy entretenidas y se aprende mucho, no es facil, pero tampoco imposible sólo es cuestión de ponerle un toquecillo, la recomiendo 100%'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-06T00:00:00+00:00'::TIMESTAMPTZ, '76547fc31e6edc29b41e36f27af6e31ae55c437b9403a3b08cb7544ce15c1235'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'Excelente profe, super buena gente y se aprende mucho en clase, las progras a veces son muy voladas pero no imposibles de hacer. Recomendada!!!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-10-28T00:00:00+00:00'::TIMESTAMPTZ, 'a771cf2fada50af9f41f7c0933a48f8508aceb4ae5a9b566724042a7d5583861'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'Es muy buena profe, lo único es que muchas veces llega tarde a la clase, pero es muy comprensiva, por lo menos da puntos por intento. En las progras si es difícil y si deja tareas, pero si explica muy bien'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'e9d35404db1d88ecf163a5e9a2abb0ae865c16ad780c8881a0e15314a4d5d13f'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'Nunca explicaba nada y asumía que uno sabía todo. Muy impuntual y desordenada hasta con las revisiones. Los exámenes los hacía a compu y no en papel, entonces por lo menos eso era más fácil. No la recomiendo si tiene otra opción.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-24T00:00:00+00:00'::TIMESTAMPTZ, '608d37d390bc6caa7ce38ad9059c60f80153a8de276a159613b8014d4c7244b0'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'c29e4db8adb0bba66dcce943eeb92cf6cb452a56e17672e5f352b004e1294e7f'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, '7b764593fe8549cc08ad1897a1b0721963e862fda460ed72a7c81495d83bed85'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'No explica muy bien. Deja tareas TODAS las clases para compensar su incapacidad de explicar la materia. Sus progras son rudas. Si uno le pone, aprende.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-21T00:00:00+00:00'::TIMESTAMPTZ, '48f56e01b553444e6bf950f8d335ac6c946f3db5d70dde578aacd88947939679'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'La profe es tuanis, pero sumamente irresponsable, minimo siempre llega media hora tarde. Deja progras muy pesadas, y el curso es duro (muy duro para lo que enseña). Al final uno termina aprendiendo todo uno mismo.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'b129a532d64f94f73620898bb06f8520bb8c8246faff4c73e8ac5f13463ce8fa'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'be3982397f972a330d07a29a01130f305e3e3279338b6ddf357083d4d15a236d'::TEXT, ARRAY[1249]::BIGINT[]),
    (305::BIGINT, 'Increiblemente irresponsable, llega cuando le da la gana. Sabe mucho de los temas, pero el desorden no la deja explicar bien'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '05015b2323ad035fcb7063627f657faff2955e1f4ba48ad229b188db62143eeb'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'Como profesora demasiado mala, sinceramente es mejor matricular con cualquier otro, Lo único que llega a hacer al aula es a hablar, pobre el asistente que le toca hacer todo el trabajo que se supone es de la profesora'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '2d8b002b45bb22a0ad5ea5d02c7a516dec9002b0b07de4344eb608ad35fa6187'::TEXT, ARRAY[1029, 1020, 1022]::BIGINT[]),
    (305::BIGINT, 'Excelente profe!'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'ff88d38c3348feb646bc152dfd2387d9183f0de146b5e16870ca4f7e0c4d24db'::TEXT, ARRAY[1020]::BIGINT[]),
    (305::BIGINT, 'Muy buena profe, explica muy bien, solo es un poco desordenada y llega tarde, pero como profe es excelente'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '63464570ec23aace5e9f09fe7e9b1a6522c8e0ffac07883b210762dfbd791e01'::TEXT, ARRAY[2517]::BIGINT[]),
    (305::BIGINT, 'La profe es buena gente, sin embargo es demasiado desordenada... cambia las progras a última hora y hay q pelearse con el asistente al final para rescatar algo... llega media hora tarde y se va media hora antes... las clases son muy rápidas y con poco contenido.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'f80211b595f5d6b3ab283c3d734d5ec549c02a49e8ce26ab784aa1efea341ba4'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'Es una excelente profesora! Pero muchas veces se emociona con los trabajos y llega tarde a clases'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'c7d0d8fdfa68386f2534ae83771e574d1dc2e4f9367c933da14e6b80e675ff8e'::TEXT, ARRAY[2517]::BIGINT[]),
    (305::BIGINT, 'Las progras son un poco enredadas y usualmente llega tarde a clases pero se le entiende muy fácilmente la materia.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '770113200f49851925b62a433d0d93461b830a99e22056f45954f7ed395dd667'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '042e7a1ef368120f6e63e381fb3f2748fb4c641aae7677ff8f451f1662e4ebac'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'Es muy buena gente! cuando debe explicar en clases lo hace muy bien! pero tiene a llegar tarde para todo xD y las progras son muy mal realizadas por lo que perjudica mucho a los estudiantes a realizarlas ya que siempre estan cambiando'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'be65409739ec7c03a7a1c71d90b1a33748db4f827b3d57baba85202ef88dd18e'::TEXT, ARRAY[1020, 1022, 1029]::BIGINT[]),
    (305::BIGINT, 'No la recomiendo porque siento que es muy fácil y no sabe explicar con mucha claridad la materia. Desorganizada, pero muy buena gente.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '322cecbd2962055e1b684dd68d8a3a70d2f172b029e12f0e63b7baba89f51268'::TEXT, ARRAY[2517]::BIGINT[]),
    (305::BIGINT, 'Es una de las mejores profesoras para empezar'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '6d94506f636ec0fa89df828c16a6905d0bc8fc327aa6b19a6c0980d57310dc21'::TEXT, ARRAY[1020, 1022, 1029]::BIGINT[]),
    (305::BIGINT, 'Relax con esta mae'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '3b8d7485754cef476fdc0bbd2e6be9e246147d3622633a45682fd94302d93295'::TEXT, ARRAY[1020]::BIGINT[]),
    (305::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'f1766c1087dfbff050dd543cc39fdc407d72ad46d908111d9b920e76541e57f9'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'Es muy buena gente, no ayuda a nadie al final, pero es buena enseñando, aunque sus progras son demasiado mal hechas, ni ella entiende que esta pidiendo.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '8e3dec13a71ba881a99145cdd592b83c69ecfbea741a7d4d35971918f9b47f2b'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (305::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, '0833d4de2198e38d38789bfbf8c6a0efc19cecfebf4d7f9135d6e0f425dea96a'::TEXT, ARRAY[1029]::BIGINT[]),
    (305::BIGINT, 'es muy buena profe, le interesa que uno aprenda en la clase, muy pura vida, nada más no le haga una estupidez y así no se la echa encima, la mae enojada si da miedillo. solo le falta ser más puntual, siempre llegaba como 20 minutos más tarde'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, '7a04f0aa12d7ac63aea631cf45b9da0ea65017b454229075383f2298c37a0752'::TEXT, ARRAY[2517]::BIGINT[]),
    (305::BIGINT, 'Es buena profe, sabe lo q hace, solo le cambiaría lo de la puntualidad pero en cuanto a materia es muy buena.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'e6bb03bbcc948320d65487a559335df4aa545a2028a86633fde7de16cf3e1fe1'::TEXT, ARRAY[2517]::BIGINT[]),
    (305::BIGINT, 'Es buena profe pero siento que le falta ser un poco más dura califican y exigir más a los estudiantes.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'ff5f1d25b81bcd6824e9be923c42bb294902e5f5c482efd6cd9e65dbf4247dae'::TEXT, ARRAY[1035, 1029]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
